#include "global.h"
#include "text.h"
#include "text_cjk.h"

// Full-width glyphs for the Simplified Chinese build. See docs/fusion/CHINESE.md.
//
// The glyphs (12px, from Fusion Pixel Font) are generated by tools/zh/zh.py in
// the same 2bpp 16x16 layout as the Latin fonts, with the ink in rows 1-12 and
// a Gen 3 style shadow, so they reuse DecompressGlyphTile and the normal text
// printer.

#if FUSION_CHINESE

#include <cjk_font.h> // build/zh/cjk_font.h

static bool32 IsSmallFont(u32 fontId)
{
    return fontId == FONT_SMALL || fontId == FONT_SMALL_NARROW;
}

static bool32 IsNarrowFont(u32 fontId)
{
    switch (fontId)
    {
    case FONT_NARROW:
    case FONT_SMALL_NARROW:
    case FONT_NARROWER:
    case FONT_SMALL_NARROWER:
    case FONT_SHORT_NARROW:
    case FONT_SHORT_NARROWER:
        return TRUE;
    default:
        return FALSE;
    }
}

static u32 GetCJKGlyphHeight(u32 fontId)
{
    switch (fontId)
    {
    case FONT_SMALL:
        return 13;
    case FONT_SMALL_NARROW:
        return 12;
    case FONT_SHORT:
    case FONT_SHORT_COPY_1:
    case FONT_SHORT_COPY_2:
    case FONT_SHORT_COPY_3:
    case FONT_SHORT_NARROW:
    case FONT_SHORT_NARROWER:
        return 14;
    default:
        return 15;
    }
}

// Moves the decompressed glyph up by one row, for the shorter small fonts.
static void ShiftCurGlyphUp(void)
{
    u32 i;

    for (i = 0; i < 7; i++)
    {
        gCurGlyph.gfxBufferTop[i] = gCurGlyph.gfxBufferTop[i + 1];
        gCurGlyph.gfxBufferTop[8 + i] = gCurGlyph.gfxBufferTop[8 + i + 1];
    }
    gCurGlyph.gfxBufferTop[7] = gCurGlyph.gfxBufferBottom[0];
    gCurGlyph.gfxBufferTop[15] = gCurGlyph.gfxBufferBottom[8];
    for (i = 0; i < 7; i++)
    {
        gCurGlyph.gfxBufferBottom[i] = gCurGlyph.gfxBufferBottom[i + 1];
        gCurGlyph.gfxBufferBottom[8 + i] = gCurGlyph.gfxBufferBottom[8 + i + 1];
    }
}

u32 GetCJKGlyphWidth(u32 glyphIndex, u32 fontId)
{
    u32 width;

    if (glyphIndex >= CJK_GLYPH_COUNT)
        return 0;

    width = sCJKGlyphWidths[glyphIndex];
    // The narrow fonts drop the shadow column.
    if (IsNarrowFont(fontId) && width == CJK_GLYPH_WIDTH)
        width--;
    return width;
}

void DecompressGlyph_CJK(u32 glyphIndex, u32 fontId)
{
    const u16 *glyphs;

    if (glyphIndex >= CJK_GLYPH_COUNT)
        glyphIndex = 0;

    glyphs = sCJKGlyphs + (0x20 * glyphIndex);
    DecompressGlyphTile(glyphs, gCurGlyph.gfxBufferTop);
    DecompressGlyphTile(glyphs + 0x8, gCurGlyph.gfxBufferTop + 8);
    DecompressGlyphTile(glyphs + 0x10, gCurGlyph.gfxBufferBottom);
    DecompressGlyphTile(glyphs + 0x18, gCurGlyph.gfxBufferBottom + 8);

    if (IsSmallFont(fontId))
        ShiftCurGlyphUp();

    gCurGlyph.width = GetCJKGlyphWidth(glyphIndex, fontId);
    gCurGlyph.height = GetCJKGlyphHeight(fontId);
}

// Full-width punctuation that shouldn't start a line (，。！？ etc.).
bool32 IsCJKNoLineStartChar(const u8 *str)
{
    static const u8 sNoLineStart[][2] = CJK_NO_LINE_START_CHARS;
    u32 i;

    for (i = 0; i < ARRAY_COUNT(sNoLineStart); i++)
    {
        if (str[0] == sNoLineStart[i][0] && str[1] == sNoLineStart[i][1])
            return TRUE;
    }
    return FALSE;
}

#endif // FUSION_CHINESE
